export const SIGNATURE_AHMAD_DATA_URI = 'data:image/png;base64,'
export const SIGNATURE_ABHIJEET_DATA_URI = 'data:image/png;base64,'

export interface SignatoryOption {
  id: string
  name: string
  label: string
  signatureDataUri: string
}

export const SIGNATORIES: Record<string, SignatoryOption> = {
  Abhijeet: {
    id: 'Abhijeet',
    name: 'Abhijeet',
    label: 'Abhijeet',
    signatureDataUri: SIGNATURE_ABHIJEET_DATA_URI
  },
  Ahmad: {
    id: 'Ahmad',
    name: 'Ahmad',
    label: 'Ahmad',
    signatureDataUri: SIGNATURE_AHMAD_DATA_URI
  }
}

export const DEFAULT_SIGNATORY = 'Abhijeet'

export function getSignatory (name?: string): SignatoryOption {
  if (name && SIGNATORIES[name]) return SIGNATORIES[name]
  if (name && name.toLowerCase().includes('ahmad')) return SIGNATORIES.Ahmad
  return SIGNATORIES.Abhijeet
}

export { DEFAULT_ITEM_TEMPLATES } from './aneeverseBilling'
